// This file is generated by AI.

// 对话者到角色的静默匹配测试。
//
// 匹配失败只是"下拉框没选中", 但错误匹配会让整段对话用错音色, 因此这里重点覆盖:
// 立绘优先、名称匹配、**包含关系**、包含关系上的歧义不猜、
// 旁白继承、显式空说话者 (旁白) 不继承。
// (别名机制已移除, 因此不再有别名相关用例。)

import { describe, expect, it } from 'vitest';

import type { Character, SayLine } from '../src/commands/voice';
import { figureIdsBySpeaker, matchCharacter, matchScene, type MatchContext } from '../src/voice/match';

function say(line: number, speaker: string | null, text: string, figure: string | null = null): SayLine {
  return {
    line,
    lineCount: 1,
    speaker,
    speakerInherited: false,
    text,
    vocal: null,
    figure,
    hash: `h${line}`,
  };
}

function character(id: string, name: string, enabled = true): Character {
  return {
    id,
    name,
    description: '',
    language: 'auto',
    references: [],
    model: null,
    starred: false,
    enabled,
    createdAt: 0,
    updatedAt: 0,
  };
}

const anon = character('anon', '千早爱音');
const soyo = character('soyo', '长崎素世');

function context(characters: Character[], dialogues: SayLine[], overrides: Record<string, string> = {}): MatchContext {
  return {
    characters,
    overrides,
    resolved: {},
    figureIds: figureIdsBySpeaker(dialogues),
  };
}

describe('figureIdsBySpeaker', () => {
  it('按归一化说话者收集立绘引用', () => {
    const map = figureIdsBySpeaker([say(0, '千早爱音', 'a', 'anon'), say(1, ' 千早爱音 ', 'b', 'anon-2')]);
    expect(map.get('千早爱音')).toEqual(new Set(['anon', 'anon-2']));
  });

  it('无立绘或无说话者的行不参与', () => {
    const map = figureIdsBySpeaker([say(0, '爱音', 'a'), say(1, null, 'b', 'anon')]);
    expect(map.size).toBe(0);
  });
});

describe('matchCharacter', () => {
  it('立绘引用命中角色 id', () => {
    // 说话者刻意不是角色名: 这一条只验证立绘这条线索本身
    const dialogues = [say(0, '同班同学', '内容', 'anon')];
    const result = matchCharacter(dialogues[0], context([anon, soyo], dialogues));
    expect(result).toEqual({ characterId: 'anon', reason: 'figureId' });
  });

  it('立绘引用命中角色名', () => {
    const dialogues = [say(0, '某人', '内容', '千早爱音')];
    const result = matchCharacter(dialogues[0], context([anon, soyo], dialogues));
    expect(result).toEqual({ characterId: 'anon', reason: 'figureId' });
  });

  it('按名称精确匹配', () => {
    const line = say(0, '长崎素世', '内容');
    expect(matchCharacter(line, context([anon, soyo], [line]))).toEqual({
      characterId: 'soyo',
      reason: 'name',
    });
  });

  it('忽略大小写与空白差异', () => {
    const line = say(0, '  anon ', '内容');
    expect(matchCharacter(line, context([character('anon', 'anon')], [line])).characterId).toBe('anon');
  });

  it('人工覆盖优先于自动匹配', () => {
    const line = say(0, '千早爱音', '内容', 'anon');
    const result = matchCharacter(line, context([anon, soyo], [line], { 千早爱音: 'soyo' }));
    expect(result).toEqual({ characterId: 'soyo', reason: 'override' });
  });

  it('覆盖指向已删除或未启用的角色时回退到自动匹配', () => {
    const disabled = { ...soyo, enabled: false };
    const line = say(0, '长崎素世', '内容');
    const result = matchCharacter(line, context([anon, disabled], [line], { 长崎素世: 'soyo' }));
    expect(result.reason).toBe('none');
  });

  it('旁白不按说话者匹配', () => {
    const line = say(0, null, '旁白内容');
    expect(matchCharacter(line, context([anon], [line]))).toEqual({
      characterId: null,
      reason: 'narration',
    });
  });

  it('无任何线索时返回 none', () => {
    const line = say(0, '路人甲', '内容');
    expect(matchCharacter(line, context([anon, soyo], [line]))).toEqual({
      characterId: null,
      reason: 'none',
    });
  });

  it('对话者里含有角色名时按包含关系匹配', () => {
    // 真实剧本里极常见的写法: 对话者带后缀 / 带括号注释
    for (const speaker of ['千早爱音（教室）', '千早爱音A', '（黑）千早爱音']) {
      const line = say(0, speaker, '内容');
      expect(matchCharacter(line, context([anon, soyo], [line]))).toEqual({
        characterId: 'anon',
        reason: 'namePartial',
      });
    }
  });

  it('角色名里含有对话者时同样匹配 (简称)', () => {
    const line = say(0, '爱音', '内容');
    const result = matchCharacter(line, context([anon, soyo], [line]));
    expect(result).toEqual({ characterId: 'anon', reason: 'namePartial' });
  });

  it('精确匹配优先于包含关系', () => {
    // 「爱音」既是精确的角色名, 也是「千早爱音」的一部分 -> 取精确的那一个
    const short = character('anon-short', '爱音');
    const line = say(0, '爱音', '内容');
    expect(matchCharacter(line, context([anon, short], [line]))).toEqual({
      characterId: 'anon-short',
      reason: 'name',
    });
  });

  it('包含关系命中更长的一方优先', () => {
    const teni = character('teni', '千早爱音');
    const partial = character('partial', '千早');
    const line = say(0, '千早爱音（黑）', '内容');
    // 两个角色都包含在对话者里, 但「千早爱音」更长 -> 更可信
    expect(matchCharacter(line, context([teni, partial], [line]))?.characterId).toBe('teni');
  });

  it('包含关系上同等强度的多个候选不猜', () => {
    const a = character('a', '爱音');
    const b = character('b', '音乃');
    const line = say(0, '爱音乃', '内容');
    // 「爱音」与「音乃」都命中且长度相同, 无法判断 -> 交给用户手选
    expect(matchCharacter(line, context([a, b], [line]))).toEqual({
      characterId: null,
      reason: 'none',
    });
  });

  it('单字角色名不参与包含关系匹配', () => {
    const single = character('single', '音');
    const line = say(0, '路人甲的音', '内容');
    expect(matchCharacter(line, context([single], [line])).characterId).toBeNull();
  });

  it('立绘引用优先于包含关系', () => {
    // 对话者里含有 anon 的名字, 但立绘明确指向 soyo
    const dialogues = [say(0, '千早爱音的替身', '内容', 'soyo')];
    const result = matchCharacter(dialogues[0], context([anon, soyo], dialogues));
    expect(result).toEqual({ characterId: 'soyo', reason: 'figureId' });
  });
});

describe('matchScene', () => {
  it('按顺序匹配整场景, 并在换人后继续匹配', () => {
    const dialogues = [
      say(0, '千早爱音', '你爱我吗？', 'anon'),
      say(1, '长崎素世', '唉？', 'soyo'),
      say(2, '千早爱音', '回答我。', 'anon'),
    ];
    const matches = matchScene(dialogues, [anon, soyo]);
    expect(matches.get(0)?.characterId).toBe('anon');
    expect(matches.get(1)?.characterId).toBe('soyo');
    expect(matches.get(2)?.characterId).toBe('anon');
  });

  it('旁白人工覆盖应用到显式旁白行', () => {
    const dialogues = [say(0, null, '第一段旁白'), say(1, '千早爱音', '台词', 'anon'), say(2, null, '第二段旁白')];
    const matches = matchScene(dialogues, [anon, soyo], { '': 'soyo' });
    expect(matches.get(0)).toEqual({ characterId: 'soyo', reason: 'override' });
    expect(matches.get(1)?.characterId).toBe('anon');
    // 显式旁白同样使用覆盖
    expect(matches.get(2)).toEqual({ characterId: 'soyo', reason: 'override' });
  });

  it('省略说话者的旁白行沿用上一条旁白的角色', () => {
    // 第 1 行是显式旁白 (可指定角色), 第 2 行是省略说话者的裸行
    const explicitNarration: SayLine = { ...say(0, null, '第一段旁白'), speakerInherited: false };
    const inheritedNarration: SayLine = { ...say(1, null, '第二段旁白'), speakerInherited: true };
    const matches = matchScene([explicitNarration, inheritedNarration], [anon, soyo], { '': 'soyo' });
    expect(matches.get(0)).toEqual({ characterId: 'soyo', reason: 'override' });
    expect(matches.get(1)).toEqual({ characterId: 'soyo', reason: 'narration' });
  });

  it('旁白在选择角色之前保持未指定', () => {
    const dialogues = [say(0, null, '旁白'), say(1, null, '旁白2')];
    const matches = matchScene(dialogues, [anon]);
    expect(matches.get(0)?.characterId).toBeNull();
    expect(matches.get(1)?.characterId).toBeNull();
  });

  it('未启用角色不参与匹配但仍占位', () => {
    const disabled = { ...anon, enabled: false };
    const dialogues = [say(0, '千早爱音', '内容', 'anon')];
    expect(matchScene(dialogues, [disabled]).get(0)?.characterId).toBeNull();
  });
});
